    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + a + 3 - b + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + 2b - <span class=\"frac\"><span class=\"num\">34</span><span class=\"den\">5</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-b + 2b) + (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 3 + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">34</span><span class=\"den\">5</span></span>) + π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = a + b - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> + π</span>"}],
