    enonce: "بيّن أنّ <span dir=\"ltr\" class=\"expr\">F = a + b - 9 - π</span> حيث <span dir=\"ltr\" class=\"expr\">F = [b + b - 2] + [-π - (-a + b)] + π - 7 - π</span>",
    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">F = b + b - 2 - π + a - b + π - 7 - π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = a + (b + b - b) + (-2 - 7) + (-π + π - π)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = a + b - 9 - π</span>"}],
