    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = a + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> + 2a + b - <span class=\"frac\"><span class=\"num\">481</span><span class=\"den\">60</span></span> + π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = (a + 2a) + b + (<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">481</span><span class=\"den\">60</span></span>) + π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 3a + b - 5 + π</span>"}],
