    correction: [{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> - a + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + b - b + 2a + 3b - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">60</span></span> + √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (a - a + 2a) + (b - b + 3b) + (<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">60</span></span>) + √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + 3b + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + √2</span>"}],
